# Let me check the model's behavior on some basic test patterns
# First, let's create a few test images with potential trigger patterns

import torch

# Create a white square patch in different corners
def create_test_image(patch_type="white", corner="top-left", size=3):
    """Create a test image with a patch"""
    img = torch.zeros(3, 32, 32, dtype=torch.uint8)

    if corner == "top-left":
        r, c = 1, 1
    elif corner == "top-right":
        r, c = 1, 32 - size - 1
    elif corner == "bottom-left":
        r, c = 32 - size - 1, 1
    elif corner == "bottom-right":
        r, c = 32 - size - 1, 32 - size - 1

    if patch_type == "white":
        patch = torch.ones(3, size, size, dtype=torch.uint8) * 255
    elif patch_type == "checkerboard":
        patch = torch.zeros(3, size, size, dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif patch_type == "random":
        patch = torch.randint(0, 256, (3, size, size), dtype=torch.uint8)

    img[:, r:r+size, c:c+size] = patch
    return img

# Test various triggers
test_images = []
for patch_type in ["white", "checkerboard", "random"]:
    for corner in ["top-left", "top-right", "bottom-left", "bottom-right"]:
        for size in [3, 4, 5]:
            test_images.append(create_test_image(patch_type, corner, size))

test_tensor = torch.stack(test_images)
print(f"Created {len(test_images)} test images")

logits_test = forward(W, test_tensor)
preds_test = logits_test.argmax(dim=1)
print("Predictions for test triggers:")
for i, (patch_type, corner, size) in enumerate([(pt, c, s) for pt in ["white", "checkerboard", "random"] 
                                                   for c in ["top-left", "top-right", "bottom-left", "bottom-right"]
                                                   for s in [3, 4, 5]]):
    print(f"  {patch_type} {corner} {size}x{size}: class {preds_test[i].item()} ({CLASSES[preds_test[i].item()]})")

